import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [nStr, dStr] = input;
const D = Number(dStr);
const MOD = 1_000_000_007;

// free[r] = すでに N より小さいと確定した、桁和 mod D が r の数の個数
let free = new Array(D).fill(0);
let tightSum = 0; // N と同じ桁を選び続けた場合の桁和 mod D
for (const ch of nStr) {
  const c = Number(ch);
  const next = new Array(D).fill(0);
  for (let r = 0; r < D; r++) {
    if (free[r] === 0) continue;
    for (let digit = 0; digit <= 9; digit++) {
      const nr = (r + digit) % D;
      next[nr] = (next[nr] + free[r]) % MOD;
    }
  }
  // N の桁より小さい数字を選ぶと、ここで「小さい」が確定する
  for (let digit = 0; digit < c; digit++) {
    const nr = (tightSum + digit) % D;
    next[nr] = (next[nr] + 1) % MOD;
  }
  tightSum = (tightSum + c) % D;
  free = next;
}

// N 自身を加え、0（桁和 0 で数えられている）を除く
const count = free[0] + (tightSum === 0 ? 1 : 0) - 1;
console.log(((count % MOD) + MOD) % MOD);
